          <ActionButton icon={Phone} color="green" onClick={onAccept} enabled={enabled} />
          {onAcceptVideo && (
            <ActionButton icon={Video} color="blue" onClick={onAcceptVideo} enabled={enabled} />
          )}
        </div>
      </motion.div>
    </motion.div>
  );
};

