    const hasDelivered = chat.history.some((m: any) => m.sender === "me" && m.status === "delivered");
    if (!hasDelivered) return;
    const timer = setTimeout(() => {
      const updatedHistory = chat.history.map((m: any) => {
        if (m.sender === "me" && m.status === "delivered") return { ...m, status: "read" };
        return m;
      });
      const updatedChat = { ...chat, history: updatedHistory };
      if (onUpdateChat) onUpdateChat(updatedChat);
      setChatsStore(prev => prev.map(c => c.id === chat.id ? updatedChat : c));
    }, 1500);
    return () => clearTimeout(timer);
  }, [chat, onUpdateChat, setChatsStore]);

  const debouncedSearch = useDebounce(searchQuery, 200);

  const filteredHistory = useMemo(() =>
    chat.history?.filter((msg: any, idx: number) => {
      if (filterBySender === 'me' && msg.sender !== 'me') return false;
      if (filterBySender === 'them' && msg.sender === 'me') return false;
      if (filterStartDate || filterEndDate) {
        const msgDate = new Date(idx * 86400000 + Date.now());
        if (filterStartDate && msgDate < new Date(filterStartDate)) return false;
        if (filterEndDate && msgDate > new Date(filterEndDate)) return false;
      }
      return debouncedSearch ? msg.text?.toLowerCase().includes(debouncedSearch.toLowerCase()) || !msg.text : true;
    }) || [],
    [chat.history, filterBySender, filterStartDate, filterEndDate, debouncedSearch]
  );

  const mediaItems = useMemo(() =>
    (chat.history || []).filter((msg: any) => {
      if (filterBySender === 'me' && msg.sender !== 'me') return false;
      if (filterBySender === 'them' && msg.sender === 'me') return false;
      if (debouncedSearch && !msg.text?.toLowerCase().includes(debouncedSearch.toLowerCase())) return false;
      if (mediaTab === 'photos') return msg.type === 'image';
      if (mediaTab === 'audio') return msg.type === 'audio';
      if (mediaTab === 'links') return typeof msg.text === 'string' && /https?:\/\//i.test(msg.text);
      return msg.type === 'image' || msg.type === 'audio' || (typeof msg.text === 'string' && /https?:\/\//i.test(msg.text));
    }),
    [chat.history, filterBySender, debouncedSearch, mediaTab]
  );

  const chatSavedMessages = useMemo(() =>
    savedMessages.filter((saved: any) => saved.chatId === chat.id),
    [savedMessages, chat.id]
  );

  const chatScheduledMessages = useMemo(() =>
    scheduledQueue.messages.filter((m: any) => m.chatId === chat.id),
    [scheduledQueue.messages, chat.id]
  );

  const flatItems = useMemo(() => {
    const groups = groupMessages(filteredHistory);
    const items: any[] = [];
    let lastDateLabel = '';
    for (const group of groups) {
      const firstMsg = group.messages[0];
      const dateLabel = formatDateLabel(firstMsg.time);
      if (dateLabel !== lastDateLabel && items.length > 0) {
        items.push({ id: `sep-${dateLabel}`, _isDateSeparator: true, _dateLabel: dateLabel });
      }
      lastDateLabel = dateLabel;
      group.messages.forEach((msg: any, mi: number) => {
        items.push({ ...msg, _groupPosition: group.groupPositions[mi], _isLastInGroup: mi === group.messages.length - 1 });
      });
    }
    return items;
  }, [filteredHistory]);

  return {
    videoOpen, setVideoOpen,
    photoOpen, setPhotoOpen,
    activePhotoUrl, setActivePhotoUrl,
    searchQuery, setSearchQuery,
    showSearch, setShowSearch,
    showMediaPanel, setShowMediaPanel,
    selectedContact, setSelectedContact,
    mediaTab, setMediaTab,
    filterBySender, setFilterBySender,
    filterStartDate, setFilterStartDate,
    filterEndDate, setFilterEndDate,
    showFilterMenu, setShowFilterMenu,
    showDateFilter, setShowDateFilter,
    showComments, setShowComments,
    activePostId, setActivePostId,
    activeReactionPicker, setActiveReactionPicker,
    showSavedPanel, setShowSavedPanel,
    bounceMsgId, setBounceMsgId,
    isNearBottom, setIsNearBottom,
    unreadSinceScroll, setUnreadSinceScroll,
    eMsgText, setMsgTextFn,
    eMorseMode, setMorseModeFn2,
    eSilentMode, setSilentModeFn2,
    eShowStickerPicker, setShowStickerPickerFn2,
    eIsRecordingVoice, setIsRecordingVoiceFn2,
    eVoiceNoteError, setVoiceNoteErrFn2,
    eScheduleDateTime, setScheduleDtFn2,
    eShowSchedulePopup, setShowSchedulePopupFn2,
    eReplyTarget, setReplyTargetFn2,
    lastTapRef,
    swipeReplyId, setSwipeReplyId,
    msgListRef,
    sendMessage,
    handleImageAttach,
    handleReactionMessage,
    filteredHistory,
    mediaItems,
    chatSavedMessages,
    chatScheduledMessages,
    flatItems,
    scheduledQueue,
    stealthMode,
    setChatsStore,
    setChannels,
    contacts,
    setContacts,
    debouncedSearch,
  };
}

import { useEffect, useRef } from "react";
import { useAppStore } from "../store";
import type { ScheduledMessage } from "../store/types";

export function useScheduledMessages() {
  const scheduledQueue = useAppStore(s => s.scheduledQueue);
  const setChats = useAppStore(s => s.setChats);

  useEffect(() => {
    if (!scheduledQueue || scheduledQueue.messages.length === 0) return;
    
    const interval = setInterval(() => {
      const now = Date.now();
      const messagesToSend = scheduledQueue.messages.filter((msg: ScheduledMessage) => msg.scheduledAt <= now);
      
      if (messagesToSend.length > 0) {
        setChats(prevChats => {
          let updatedChats = [...prevChats];
          for (const msg of messagesToSend) {
            const chatIndex = updatedChats.findIndex((c: any) => c.id === msg.chatId);
            if (chatIndex > -1) {
              const chat = updatedChats[chatIndex];
              const newHistory = [...(chat.history || []), {
                id: Date.now() + Math.random(),
                text: msg.text,
                sender: "me",
                status: "delivered"
              }];
              updatedChats[chatIndex] = { ...chat, history: newHistory, message: msg.text, time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) };
            }
          }
          return updatedChats;
        });

        messagesToSend.forEach((msg: ScheduledMessage) => scheduledQueue.removeMessage(msg.id));
      }
    }, 1000);
    
    return () => clearInterval(interval);
  }, [scheduledQueue, setChats]);
}

import { useEffect, useRef, useState } from 'react';

export function useVoiceWaveformAudio(audioUrl?: string, stream?: MediaStream | null, durationSec = 0) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isReady, setIsReady] = useState(false);
  const [staticWave, setStaticWave] = useState<number[]>([]);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourceRef = useRef<AudioBufferSourceNode | MediaStreamAudioSourceNode | null>(null);
  const bufferRef = useRef<AudioBuffer | null>(null);
  const startTimeRef = useRef<number>(0);
  const pausedAtRef = useRef<number>(0);
  const animationRef = useRef<number | null>(null);
  const seekingRef = useRef(false);

  useEffect(() => {
    let active = true;
    const initAudio = async () => {
      const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
      if (!AudioCtx) return;

      const ctx = new AudioCtx();
      audioCtxRef.current = ctx;

      const analyser = ctx.createAnalyser();
      analyser.fftSize = 64;
      analyserRef.current = analyser;

      if (stream) {
        const source = ctx.createMediaStreamSource(stream);
        source.connect(analyser);
        sourceRef.current = source;
        setIsPlaying(true);
      } else if (audioUrl) {
        try {
          const resp = await fetch(audioUrl);
          if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
          const arrayBuffer = await resp.arrayBuffer();
          if (!active) return;
          bufferRef.current = await ctx.decodeAudioData(arrayBuffer);
          setIsReady(true);
        } catch {
          const sampleRate = ctx.sampleRate;
          const length = Math.max(1, sampleRate * (durationSec || 1));
          const fallbackBuffer = ctx.createBuffer(1, length, sampleRate);
          const data = fallbackBuffer.getChannelData(0);
          let lastOut = 0;
          for (let i = 0; i < length; i++) {
            const white = (Math.random() * 2 - 1) * 0.5;
            lastOut = lastOut + (0.05 * (white - lastOut));
            let envelope = Math.abs(Math.sin((i / sampleRate) * 2));
            if (Math.sin((i / sampleRate) * 5) < -0.5) envelope = 0.05;
            data[i] = lastOut * envelope;
          }
          bufferRef.current = fallbackBuffer;
          setIsReady(true);
        }
      } else {
        const sampleRate = ctx.sampleRate;
        const length = Math.max(1, sampleRate * (durationSec || 1));
        const buffer = ctx.createBuffer(1, length, sampleRate);
        const data = buffer.getChannelData(0);
        let lastOut = 0;
        for (let i = 0; i < length; i++) {
          const white = (Math.random() * 2 - 1) * 0.5;
          lastOut = lastOut + (0.05 * (white - lastOut));
          let envelope = Math.abs(Math.sin((i / sampleRate) * 2));
          if (Math.sin((i / sampleRate) * 5) < -0.5) envelope = 0.05;
          data[i] = lastOut * envelope;
        }
        bufferRef.current = buffer;
        setIsReady(true);
      }
    };

    initAudio();

    return () => {
      active = false;
      if (audioCtxRef.current && audioCtxRef.current.state !== 'closed') {
        audioCtxRef.current.close().catch(console.error);
      }
      if (animationRef.current) cancelAnimationFrame(animationRef.current);
    };
  }, [durationSec, audioUrl, stream]);

  useEffect(() => {
    if (bufferRef.current) {
      const data = bufferRef.current.getChannelData(0);
      const bars = 40;
      const step = Math.floor(data.length / bars);
      const peaks = [];
      for (let i = 0; i < bars; i++) {
        let max = 0;
        for (let j = 0; j < step; j++) {
          const val = Math.abs(data[i * step + j]);
          if (val > max) max = val;
        }
        peaks.push(Math.max(0.05, max * 5));
      }
      setStaticWave(peaks);
    } else {
      setStaticWave(Array.from({ length: 40 }, () => Math.random() * 0.5 + 0.1));
    }
  }, [bufferRef.current]);

  const startPlaybackAt = async (offset: number) => {
    if (!audioCtxRef.current || !bufferRef.current || !analyserRef.current) return;
    const ctx = audioCtxRef.current;
    if (ctx.state === 'suspended') await ctx.resume();
    if (sourceRef.current) {
      if ('stop' in sourceRef.current) sourceRef.current.stop();
      sourceRef.current.disconnect();
    }
    const source = ctx.createBufferSource();
    source.buffer = bufferRef.current;
    source.connect(analyserRef.current);
    analyserRef.current.connect(ctx.destination);
    source.start(0, offset);
    startTimeRef.current = ctx.currentTime - offset;
    sourceRef.current = source;
    setIsPlaying(true);
    pausedAtRef.current = offset;
    const endDuration = durationSec;
    source.onended = () => {
      if (ctx.currentTime - startTimeRef.current >= endDuration - 0.1) {
        setIsPlaying(false);
        setProgress(0);
        pausedAtRef.current = 0;
        if (animationRef.current) cancelAnimationFrame(animationRef.current);
      }
    };
  };

  const togglePlayback = async () => {
    if (!audioCtxRef.current || !bufferRef.current || !analyserRef.current) return;
    if (isPlaying) {
      if (sourceRef.current) {
        if ('stop' in sourceRef.current) sourceRef.current.stop();
        sourceRef.current.disconnect();
      }
      pausedAtRef.current = (audioCtxRef.current.currentTime - startTimeRef.current) % durationSec;
      setIsPlaying(false);
    } else {
      await startPlaybackAt(pausedAtRef.current);
    }
  };

  const handleSeek = async (nextProgress: number) => {
    if (!durationSec) return;
    const clamped = Math.max(0, Math.min(1, nextProgress));
    const nextOffset = durationSec * clamped;
    setProgress(clamped);
    pausedAtRef.current = nextOffset;
    if (isPlaying) {
      seekingRef.current = true;
      await startPlaybackAt(nextOffset);
      seekingRef.current = false;
    }
  };

  const updateProgress = () => {
    if (seekingRef.current) return;
    if (!isPlaying || !audioCtxRef.current) return;
    const p = ((audioCtxRef.current.currentTime - startTimeRef.current) % durationSec) / durationSec;
    setProgress(p);
  };

  return {
    isPlaying,
    progress,
    isReady,
    staticWave,
    analyserRef,
    audioCtxRef,
    startTimeRef,
    animationRef,
    togglePlayback,
    handleSeek,
    updateProgress,
    durationSec,
  };
}

import { readFileSync } from 'node:fs';
