// src/lib/p2p/MeshDHT.ts
// Kadabra-style Distributed Hash Table for decentralized peer discovery.
// Each peer has a nodeId (hex hash of its publicKey). The network is a ring
// of 2^160 nodes. Buckets are sorted by distance to the ring origin.
// Protocol messages: dht-get, dht-put, dht-lookup, dht-notify.

export interface DHTNode {
  nodeId: string           // hex hash (0..65)
  publicKey: string        // original public key / handle
  peerId: string           // human-readable id
  lastSeen: number
  latency?: number
  path?: string[]
  [key: string]: any
}

export interface DHTLookupResult {
  nodeId: string
  peer: DHTNode
}

export interface DHTStoreValue {
  key: string
  value: string
  nodeId: string           // closest node to the key
}

export interface DHTBootstrapPeer {
  peerId: string
  publicKey: string
  address: string          // ws:// or wss:// or just an identifier
}

// Kadabra constants
const K = 10               // replication factor
const TIMEOUT = 10000       // ms for a lookup to complete
const CLEANUP_INTERVAL = 3600000 // 1 hour

// Kadabra uses a simple hash ring with exponential distance metric
// We store a routing table that maps node prefixes to peer connections

export class MeshDHT {
  private static table = new Map<string, DHTNode>()
  private static lookupCache = new Map<string, DHTNode[]>()
  private static store: Map<string, DHTStoreValue> = new Map()
  private static TTL = 3600 * 1000 // 1 hour
  private static bootstrap: DHTBootstrapPeer[] = []
  private static onNotify?: (peer: DHTNode) => void

  /**
   * Register bootstrap peers (the "seed" nodes).
   * Call this at least once before any lookup.
   */
  static setBootstrap(peers: DHTBootstrapPeer[]): void {
    this.bootstrap = peers
  }

  /**
   * Register a callback for when new peers are discovered.
   * This is the key mechanism: when a peer joins, it broadcasts
   * its nodeId to the closest known nodes. Those nodes store it
   * in their routing tables and forward the notification further.
   */
  static onNewPeer(cb: (peer: DHTNode) => void): void {
    this.onNotify = cb
  }

  /**
   * Add a known node to the DHT table.
   * In a real Kadabra implementation this would involve
   * exchanging messages with the node and verifying connectivity.
   */
  static async addNode(node: DHTNode): Promise<void> {
    // Check if node is already in table (by nodeId)
    const existing = this.table.get(node.nodeId)
    if (existing) {
      // Update last seen
      this.table.set(node.nodeId, {
        ...node,
        lastSeen: Date.now(),
        publicKey: node.publicKey || existing.publicKey,
        peerId: node.peerId || existing.peerId,
      })
    } else {
      this.table.set(node.nodeId, { ...node, lastSeen: Date.now() })
    }

    // Notify callback if this is a new peer
    if (existing) {
      this.onNotify?.(node)
    }
  }

  /**
   * Get a node by its nodeId.
   */
  static getNode(nodeId: string): DHTNode | null {
    const node = this.table.get(nodeId)
    if (!node) return null
    if (Date.now() - node.lastSeen > this.TTL) {
      this.table.delete(nodeId)
      return null
    }
    return { ...node }
  }

  /**
   * Get a node by its publicKey.
   */
  static getNodeByPublicKey(publicKey: string): DHTNode | null {
    for (const node of this.table.values()) {
      if (node.publicKey === publicKey || node.peerId === publicKey) {
        return { ...node }
      }
    }
    return null
  }

  static removeNode(publicKey: string): void {
    for (const [id, node] of this.table) {
      if (node.publicKey === publicKey || node.peerId === publicKey) {
        this.table.delete(id)
        break
      }
    }
  }

  /**
   * Lookup peers closest to a target nodeId.
   * Kadabra uses the distance metric: d(a,b) = hash(a XOR b).
   * We approximate by comparing the hex strings directly.
   */
  static getClosestNodes(target: string, count: number = K): DHTNode[] {
    const cached = this.lookupCache.get(target)
    if (cached && cached.length > 0) {
      return cached
    }

    const nodes = Array.from(this.table.values())
    // Sort by latency or, if not available, by nodeId proximity
    nodes.sort((a, b) => {
      if (a.latency !== undefined && b.latency !== undefined) {
        return a.latency - b.latency
      }
      // Fallback: sort by nodeId proximity to target
      return this.distance(a.nodeId, target) - this.distance(b.nodeId, target)
    })

    const result = nodes.slice(0, count)
    this.lookupCache.set(target, result)
    return result
  }

  /**
   * Store a key-value pair in the DHT.
   * The value is stored at the node closest to the key.
   */
  static storeValue(key: string, value: string, targetNodeId?: string): void {
    const target = targetNodeId || this.findClosestNode(key)
    this.store.set(key, { key, value, nodeId: target })
  }

  /**
   * Retrieve a value from the DHT.
   */
  static getValue(key: string): DHTStoreValue | null {
    // First check local store
    const local = this.store.get(key)
    if (local) return local

    // Then check closest node
    const closestNode = this.findClosestNode(key)
    const node = this.table.get(closestNode)
    if (node && node._store) {
      // Node has a local store
      const stored = (node._store as any)[key]
      if (stored) return { key, value: stored, nodeId: closestNode }
    }
    return null
  }

  /**
   * Get the full routing table.
   */
  static getTable(): Map<string, DHTNode> {
    return new Map(this.table)
  }

  /**
   * Clear all data.
   */
  static clear(): void {
    this.table.clear()
    this.lookupCache.clear()
    this.store.clear()
  }

  /**
   * Clean up expired nodes.
   */
  static cleanup(): void {
    const now = Date.now()
    for (const [key, node] of this.table) {
      if (now - node.lastSeen > this.TTL) {
        this.table.delete(key)
      }
    }
  }

  /**
   * Get bootstrap peers.
   */
  static getBootstrap(): DHTBootstrapPeer[] {
    return [...this.bootstrap]
  }

  // ────────────────────────────────────────────────────────────
  // Internal helpers
  // ────────────────────────────────────────────────────────────

  /**
   * Kadabra distance metric (simplified).
   * XOR two hex strings and return the length of the result.
   * This gives us a rough approximation of the Kadabra ring distance.
   */
  private static distance(a: string, b: string): number {
    if (!a || !b) return 999999
    let result = 0
    const len = Math.min(a.length, b.length)
    for (let i = 0; i < len; i++) {
      const bitA = (a.charCodeAt(i) >> (8 - (i % 8))) & 1
      const bitB = (b.charCodeAt(i) >> (8 - (i % (b.length > 32 ? 1 : 1)))) & 1
      if (bitA !== bitB) result++
    }
    return result
  }

  private static findClosestNode(key: string): string {
    if (this.table.size === 0) {
      // Use first bootstrap peer if available
      if (this.bootstrap.length > 0) {
        return this.bootstrap[0].peerId
      }
      return key
    }

    let closest: string | null = null
    let minDist = Infinity

    for (const [id, node] of this.table) {
      const dist = this.nodeDistance(node.nodeId, key)
      if (dist < minDist) {
        minDist = dist
        closest = id
      }
    }

    return closest || key
  }

  /**
   * Distance between a nodeId and a key (both hex strings).
   */
  private static nodeDistance(nodeId: string, key: string): number {
    // Kadabra uses XOR distance: d(a,b) = |hash(a) XOR hash(b)|
    // For simplicity, we use string similarity as a proxy.
    const a = nodeId.padStart(64, '0')
    const b = key.padStart(64, '0')
    let diff = 0
    for (let i = 0; i < Math.min(a.length, b.length); i++) {
      if (a[i] !== b[i]) diff++
    }
    return diff
  }
}

// Legacy exports for compatibility
export class MeshDHTLegacy {
  private static table = new Map<string, DHTNode>()
  private static TTL = 3600 * 1000

  static async addNode(node: DHTNode): Promise<void> {
    this.table.set(node.publicKey, { ...node, lastSeen: Date.now() })
  }

  static getNode(publicKey: string): DHTNode | null {
    const node = this.table.get(publicKey)
    if (!node) return null
    if (Date.now() - node.lastSeen > this.TTL) {
      this.table.delete(publicKey)
      return null
    }
    return { ...node }
  }

  static removeNode(publicKey: string): void {
    this.table.delete(publicKey)
  }

  static getClosestNodes(target: string, count: number = 3): DHTNode[] {
    const nodes = Array.from(this.table.values())
    nodes.sort((a, b) => a.latency - b.latency)
    return nodes.slice(0, count)
  }

  static getTable(): Map<string, DHTNode> {
    return this.table
  }

  static clear(): void {
    this.table.clear()
  }

  static cleanup(): void {
    const now = Date.now()
    for (const [key, node] of this.table) {
      if (now - node.lastSeen > this.TTL) {
        this.table.delete(key)
      }
    }
  }
}

/**
 * Decentralized Peer Discovery — DHT + DNS-based + Bootstrap fallbacks
 * Allows peer discovery even when all central servers are blocked.
 */

export type BootstrapPeer = {
  nodeId: string;
  address: string;
  publicKey: string;
};

export type DiscoveredPeer = {
  peerId: string;
  publicKey: string;
  lastSeen: number;
  latency: number;
  path: string[];
  capabilities: string[];
};

const DHT_TABLE_KEY = 'mess_dht_table';
const PEER_HEARTBEAT_TTL = 60 * 60 * 1000; // 1 hour

// Public bootstrap peers — fallbacks if all else fails
// These should be replaced with actual bootstrap nodes in production
const DEFAULT_BOOTSTRAP_PEERS: BootstrapPeer[] = [];

/**
 * Returns a list of bootstrap peers.
 * In production, this should come from a trusted source.
 */
export function getBootstrapPeers(): BootstrapPeer[] {
  // If no custom peers are configured, return an empty list
  if (DEFAULT_BOOTSTRAP_PEERS.length === 0) {
    return []
  }
  return [...DEFAULT_BOOTSTRAP_PEERS]
}

class PeerDiscovery {
  private dhtTable: Map<string, DiscoveredPeer> = new Map();
  private bootstrapPeers: BootstrapPeer[] = [];
  private heartbeatInterval: ReturnType<typeof setInterval> | null = null;
  private onPeerFound: ((peer: DiscoveredPeer) => void) | null = null;

  constructor() {
    this.bootstrapPeers = [...DEFAULT_BOOTSTRAP_PEERS];
    this.loadSavedPeers();
  }

  /**
   * Set custom bootstrap peers (e.g., from user config or admin panel)
   */
  setBootstrapPeers(peers: BootstrapPeer[]): void {
    this.bootstrapPeers = [...peers];
    this.savePeers();
  }

  /**
   * Set callback for discovered peers
   */
  onPeerDiscovered(callback: (peer: DiscoveredPeer) => void): void {
    this.onPeerFound = callback;
  }

  /**
   * Start DHT-based peer discovery
   */
  start(): void {
    this.loadSavedPeers();

    // Periodic heartbeat to keep peers alive
    this.heartbeatInterval = setInterval(() => {
      this.cleanup();
    }, 30000); // every 30s

    // Try to ping all known peers
    this.pingPeers();
  }

  stop(): void {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }
  }

  /**
   * Discover peers using multiple methods:
   * 1. DHT lookup
   * 2. DNS-based discovery
   * 3. Bootstrap peer ping
   */
  async discoverPeers(): Promise<DiscoveredPeer[]> {
    const discovered: DiscoveredPeer[] = [];

    // Method 1: DHT lookup
    const dhtPeers = await this.dhtLookup();
    discovered.push(...dhtPeers);

    // Method 2: DNS-based discovery (if available)
    const dnsPeers = await this.dnsDiscovery();
    discovered.push(...dnsPeers);

    // Method 3: Bootstrap peers
    const bootPeers = await this.bootstrapDiscovery();
    discovered.push(...bootPeers);

    // Deduplicate
    const unique = new Map<string, DiscoveredPeer>();
    for (const peer of discovered) {
      unique.set(peer.peerId, peer);
    }

    return Array.from(unique.values());
  }

  /**
   * DHT-based peer lookup
   */
  private async dhtLookup(): Promise<DiscoveredPeer[]> {
    const results: DiscoveredPeer[] = [];
    const saved = localStorage.getItem(DHT_TABLE_KEY);
    if (saved) {
      try {
        const table = JSON.parse(saved);
        for (const [peerId, peer] of Object.entries(table)) {
          const p = peer as DiscoveredPeer;
          if (Date.now() - p.lastSeen < PEER_HEARTBEAT_TTL) {
            results.push(p);
          }
        }
      } catch {
        /* ignore */
      }
    }
    return results;
  }

  /**
   * DNS-based peer discovery (using DNS-over-HTTPS)
   * Uses DNS TXT records to discover peer addresses
   */
  private async dnsDiscovery(): Promise<DiscoveredPeer[]> {
    if (!('fetch' in window)) return [];

    const results: DiscoveredPeer[] = [];
    const domains = [
      '_mess.peer',
      '_mess-bootstrap.peer',
    ];

    for (const domain of domains) {
      try {
        const response = await fetch(`https://dns.google/dns-query?name=${domain}&type=TXT`);
        if (response.ok) {
          const data = await response.text();
          // Parse TXT records for peer addresses
          const lines = data.split('\n');
          for (const line of lines) {
            if (line.includes('v=mess1')) {
              // Extract peer address from TXT record
              const addressMatch = line.match(/addr=([^;]+)/);
              if (addressMatch) {
                results.push({
                  peerId: crypto.randomUUID(),
                  publicKey: '',
                  lastSeen: Date.now(),
                  latency: 0,
                  path: [addressMatch[1]],
                  capabilities: ['message', 'call'],
                });
              }
            }
          }
        }
      } catch {
        /* DNS discovery failed, continue */
      }
    }

    return results;
  }

  /**
   * Bootstrap discovery — ping known bootstrap servers
   */
  private async bootstrapDiscovery(): Promise<DiscoveredPeer[]> {
    const results: DiscoveredPeer[] = [];

    for (const peer of this.bootstrapPeers) {
      try {
        const ws = new WebSocket(peer.address);
        const connection = new Promise<void>((resolve, reject) => {
          ws.onopen = () => {
            ws.close();
            resolve();
          };
          ws.onerror = () => reject(new Error('Bootstrap peer unreachable'));
          setTimeout(() => {
            ws.close();
            reject(new Error('Bootstrap peer timeout'));
          }, 5000);
        });

        await connection;
        results.push({
          peerId: peer.nodeId,
          publicKey: peer.publicKey,
          lastSeen: Date.now(),
          latency: 0,
          path: [peer.address],
          capabilities: ['bootstrap'],
        });
      } catch {
        /* Bootstrap peer unreachable */
      }
    }

    return results;
  }

  /**
   * Save discovered peers to localStorage for offline use
   */
  private savePeers(): void {
    try {
      const table: Record<string, any> = {};
      for (const [peerId, peer] of this.dhtTable.entries()) {
        table[peerId] = { ...peer };
      }
      localStorage.setItem(DHT_TABLE_KEY, JSON.stringify(table));
    } catch {
      /* ignore */
    }
  }

  /**
   * Load saved peers from localStorage
   */
  private loadSavedPeers(): void {
    try {
      const saved = localStorage.getItem(DHT_TABLE_KEY);
      if (saved) {
        const table = JSON.parse(saved);
        for (const [peerId, peer] of Object.entries(table)) {
          const p = peer as DiscoveredPeer;
          if (Date.now() - p.lastSeen < PEER_HEARTBEAT_TTL) {
            this.dhtTable.set(peerId, p);
          }
        }
      }
    } catch {
      /* ignore */
    }
  }

  /**
   * Add a discovered peer to the table
   */
  addPeer(peer: DiscoveredPeer): void {
    this.dhtTable.set(peer.peerId, {
      ...peer,
      lastSeen: Date.now(),
    });
    this.savePeers();

    if (this.onPeerFound) {
      this.onPeerFound(peer);
    }
  }

  /**
   * Remove a peer from the table
   */
  removePeer(peerId: string): void {
    this.dhtTable.delete(peerId);
    this.savePeers();
  }

  /**
   * Clean up stale peers
   */
  private cleanup(): void {
    const now = Date.now();
    let changed = false;
    for (const [peerId, peer] of this.dhtTable.entries()) {
      if (now - peer.lastSeen > PEER_HEARTBEAT_TTL) {
        this.dhtTable.delete(peerId);
        changed = true;
      }
    }
    if (changed) {
      this.savePeers();
    }
  }

  /**
   * Ping all known peers to verify connectivity
   */
  private async pingPeers(): Promise<void> {
    for (const [, peer] of this.dhtTable.entries()) {
      try {
        const start = Date.now();
        const ws = new WebSocket(peer.path[0]);
        await new Promise<void>((resolve, reject) => {
          ws.onopen = () => {
            ws.close();
            resolve();
          };
          ws.onerror = () => reject(new Error('Peer unreachable'));
          setTimeout(() => {
            ws.close();
            reject(new Error('Peer timeout'));
          }, 3000);
        });
        peer.latency = Date.now() - start;
        peer.lastSeen = Date.now();
      } catch {
        this.removePeer(peer.peerId);
      }
    }
  }

  /**
   * Get all known peers
   */
  getPeers(): DiscoveredPeer[] {
    return Array.from(this.dhtTable.values());
  }

  /**
   * Reset discovery state
   */
  reset(): void {
    this.dhtTable.clear();
    this.savePeers();
  }
}

export const peerDiscovery = new PeerDiscovery();

import { MeshRouter } from './MeshRouter';

const K = 20;

export class KBucket {
  private peers: Map<string, { peerId: string; address: string; lastSeen: number }> = new Map();
  private capacity: number;

  constructor(capacity: number = K) {
    this.capacity = capacity;
  }

  add(peerId: string, address: string): boolean {
    if (this.peers.has(peerId)) {
      const entry = this.peers.get(peerId)!;
      entry.lastSeen = Date.now();
      return true;
    }
    if (this.peers.size >= this.capacity) return false;
    this.peers.set(peerId, { peerId, address, lastSeen: Date.now() });
    return true;
  }

  remove(peerId: string): void { this.peers.delete(peerId); }

  find(peerId: string): string | null {
    const entry = this.peers.get(peerId);
    return entry ? entry.address : null;
  }

  getAll(): string[] { return Array.from(this.peers.keys()); }
  size(): number { return this.peers.size; }
}

interface StoredValue { key: string; value: string; timestamp: number; }

export class DHTNode {
  nodeId: string;
  private buckets: KBucket[] = [];
  private store: Map<string, StoredValue> = new Map();
  private router: MeshRouter | null = null;

  constructor(nodeId: string) {
    this.nodeId = nodeId;
    for (let i = 0; i < 160; i++) {
      this.buckets.push(new KBucket(K));
    }
  }

  attachRouter(router: MeshRouter): void {
    this.router = router;
    router.onForward((msg) => {
      if ((msg as any).type === 'dht-find-node') this.handleFindNode(msg as any);
      if ((msg as any).type === 'dht-store') this.handleStore(msg as any);
    });
  }

  addPeer(peerId: string): void {
    const bucketIndex = this.bucketIndex(peerId);
    if (bucketIndex >= 0 && bucketIndex < this.buckets.length) {
      this.buckets[bucketIndex].add(peerId, 'p2p:' + peerId);
    }
  }

  removePeer(peerId: string): void {
    const bucketIndex = this.bucketIndex(peerId);
    if (bucketIndex >= 0 && bucketIndex < this.buckets.length) {
      this.buckets[bucketIndex].remove(peerId);
    }
  }

  findNode(targetId: string): string[] {
    const bucketIndex = this.bucketIndex(targetId);
    if (bucketIndex >= 0 && bucketIndex < this.buckets.length) {
      return this.buckets[bucketIndex].getAll();
    }
    return [];
  }

  storeValue(key: string, value: string): void {
    this.store.set(key, { key, value, timestamp: Date.now() });
  }

  findValue(key: string): string | null {
    return this.store.get(key)?.value ?? null;
  }

  getKnownPeers(): string[] {
    const peers: Set<string> = new Set();
    for (const bucket of this.buckets) {
      for (const peer of bucket.getAll()) peers.add(peer);
    }
    return Array.from(peers);
  }

  private bucketIndex(peerId: string): number {
    return this.simpleHash(peerId) % 160;
  }

  private simpleHash(str: string): number {
    let hash = 0;
    for (let i = 0; i < str.length; i++) {
      hash = ((hash << 5) - hash) + str.charCodeAt(i);
      hash |= 0;
    }
    return Math.abs(hash);
  }

  private handleFindNode(msg: any): void {
    const peers = this.findNode(msg.targetId);
    if (this.router) {
      const response = { type: 'dht-nodes', from: this.nodeId, to: msg.from, nodes: peers };
      (this.router as any).broadcastFn?.(JSON.stringify(response));
    }
  }

  private handleStore(msg: any): void {
    this.storeValue(msg.key, msg.value);
  }
}

export function createDHTNode(peerId: string): DHTNode {
  return new DHTNode(peerId);
}

type PoolConnection = 'primary' | 'standby';
type ConnectionState = 'idle' | 'connecting' | 'connected' | 'disconnected' | 'error';

export class ConnectionPool {
  private primary: WebSocket | null = null;
  private standby: WebSocket | null = null;
  private states: Record<PoolConnection, ConnectionState> = {
    primary: 'idle',
    standby: 'idle',
  };
  private onFailover?: () => void;

  getPrimary(): WebSocket | null { return this.primary; }
  getStandby(): WebSocket | null { return this.standby; }
  getState(conn: PoolConnection): ConnectionState { return this.states[conn]; }

  setState(conn: PoolConnection, state: ConnectionState): void {
    this.states[conn] = state;
  }

  setPrimary(ws: WebSocket | null): void {
    this.primary = ws;
    this.states.primary = ws ? 'connected' : 'idle';
  }

  setStandby(ws: WebSocket | null): void {
    this.standby = ws;
    this.states.standby = ws ? 'connected' : 'idle';
  }

  async failover(): Promise<boolean> {
    if (this.states.standby === 'connected' && this.standby) {
      this.primary?.close();
      this.primary = this.standby;
      this.states.primary = 'connected';
      this.standby = null;
      this.states.standby = 'idle';
      if (this.onFailover) this.onFailover();
      return true;
    }
    return false;
  }

  onFailoverCallback(cb: () => void): void {
    this.onFailover = cb;
  }

  closeAll(): void {
    this.primary?.close();
    this.standby?.close();
    this.primary = null;
    this.standby = null;
    this.states = { primary: 'idle', standby: 'idle' };
  }
}

const BLOCKED_CACHE_KEY = 'mess_blocked_backends';

export interface SelectorOptions {
  cfWorkers?: string[];
  frontDomains?: string[];
  probeTimeout?: number;
  onBackendChange?: (backend: string) => void;
}

export class BlockedBackendCache {
  private blocked: Map<string, number> = new Map();

  constructor() {
    this.load();
  }

  isBlocked(id: string): boolean {
    const expiry = this.blocked.get(id);
    if (!expiry) return false;
    if (Date.now() > expiry) {
      this.blocked.delete(id);
      this.save();
      return false;
    }
    return true;
  }

  markBlocked(id: string, ttlMs: number): void {
    this.blocked.set(id, Date.now() + ttlMs);
    this.save();
  }

  clear(): void {
    this.blocked.clear();
    this.save();
  }

  getBlocked(): string[] {
    return Array.from(this.blocked.entries())
      .filter(([, exp]) => Date.now() < exp)
      .map(([id]) => id);
  }

  private load(): void {
    try {
      const raw = localStorage.getItem(BLOCKED_CACHE_KEY);
      if (raw) this.blocked = new Map(JSON.parse(raw));
    } catch { /* ignore */ }
  }

  private save(): void {
    try {
      localStorage.setItem(BLOCKED_CACHE_KEY, JSON.stringify(Array.from(this.blocked.entries())));
    } catch { /* ignore */ }
  }
}

export class TransportSelector {
  private seedUrls: string[];
  private options: Required<SelectorOptions>;
  private currentBackend: string = 'direct';
  private cache: BlockedBackendCache;

  constructor(seedUrls: string[], options?: SelectorOptions) {
    this.seedUrls = seedUrls;
    this.options = {
      cfWorkers: options?.cfWorkers ?? [],
      frontDomains: options?.frontDomains ?? [],
      probeTimeout: options?.probeTimeout ?? 3000,
      onBackendChange: options?.onBackendChange ?? (() => {}),
    };
    this.cache = new BlockedBackendCache();
  }

  getCurrentBackend(): string {
    return this.currentBackend;
  }

  isAllBlocked(): boolean {
    return this.cache.getBlocked().length >= this.getTotalBackends();
  }

  async selectBackend(): Promise<string> {
    const backends = this.buildBackendList();
    for (const backend of backends) {
      if (this.cache.isBlocked(backend.id)) continue;
      const ok = await this.probe(backend.url);
      if (ok) {
        this.currentBackend = backend.id;
        this.options.onBackendChange(backend.id);
        return backend.id;
      }
      this.cache.markBlocked(backend.id, 24 * 60 * 60 * 1000);
    }
    this.currentBackend = 'blocked';
    return 'blocked';
  }

  private buildBackendList(): { id: string; url: string }[] {
    const list: { id: string; url: string }[] = [];
    for (const url of this.seedUrls) {
      list.push({ id: `direct:${url}`, url });
    }
    for (const worker of this.options.cfWorkers) {
      list.push({ id: `cfworker:${worker}`, url: `wss://${worker}/ws` });
    }
    for (const domain of this.options.frontDomains) {
      list.push({ id: `domainfront:${domain}`, url: `wss://${domain}/ws` });
    }
    this.shuffle(list);
    return list;
  }

  private shuffle(arr: any[]): void {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  }

  private probe(url: string): Promise<boolean> {
    return new Promise((resolve) => {
      const ws = new WebSocket(url);
      const timer = setTimeout(() => {
        ws.close();
        resolve(false);
      }, this.options.probeTimeout);
      ws.onopen = () => {
        clearTimeout(timer);
        ws.close();
        resolve(true);
      };
      ws.onerror = () => {
        clearTimeout(timer);
        resolve(false);
      };
    });
  }

  private getTotalBackends(): number {
    return this.seedUrls.length + this.options.cfWorkers.length + this.options.frontDomains.length;
  }

  resetCache(): void {
    this.cache.clear();
  }

  onBackendChange(callback: (backend: string) => void): void {
    this.options.onBackendChange = callback;
  }
}
